const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');
const bcrypt = require('bcrypt');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });
const MASTER_KEY = Buffer.from(process.env.MASTER_KEY || crypto.randomBytes(32).toString('hex'), 'hex');
const JWT_SECRET = process.env.JWT_SECRET || crypto.randomBytes(64).toString('hex');

// Secure key derivation for per-user encryption
class KeyManager {
  constructor(masterKey) {
    this.masterKey = masterKey;
    this.keyCache = new Map();
  }

  deriveUserKey(userId) {
    if (this.keyCache.has(userId)) return this.keyCache.get(userId);
    const derived = crypto.createHmac('sha256', this.masterKey)
      .update(`user-encryption-key:${userId}`)
      .digest();
    this.keyCache.set(userId, derived);
    return derived;
  }
}

const keyManager = new KeyManager(MASTER_KEY);

// Token generation with secure random
function generateSessionToken() {
  return crypto.randomBytes(32).toString('base64url');
}

// Constant-time comparison for tokens
function safeCompare(a, b) {
  if (typeof a !== 'string' || typeof b !== 'string') return false;
  const bufA = Buffer.from(a, 'utf8');
  const bufB = Buffer.from(b, 'utf8');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

// Encrypt sensitive data with AES-256-GCM
function encryptData(plaintext, userId) {
  const key = keyManager.deriveUserKey(userId);
  const iv = crypto.randomBytes(12);
  const cipher = crypto.createCipheriv('aes-256-gcm', key, iv);
  const encrypted = Buffer.concat([cipher.update(plaintext, 'utf8'), cipher.final()]);
  const tag = cipher.getAuthTag();
  return { iv: iv.toString('base64'), data: encrypted.toString('base64'), tag: tag.toString('base64') };
}

// Decrypt sensitive data
function decryptData(encObj, userId) {
  const key = keyManager.deriveUserKey(userId);
  const iv = Buffer.from(encObj.iv, 'base64');
  const data = Buffer.from(encObj.data, 'base64');
  const tag = Buffer.from(encObj.tag, 'base64');
  const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
  decipher.setAuthTag(tag);
  return Buffer.concat([decipher.update(data), decipher.final()]).toString('utf8');
}

// Password reset token with expiry
class PasswordResetManager {
  constructor() {
    this.tokens = new Map(); // token -> { userId, expiresAt, used }
  }

  async createResetToken(userId) {
    const token = generateSessionToken();
    const hashedToken = crypto.createHash('sha256').update(token).digest('hex');
    this.tokens.set(hashedToken, {
      userId,
      expiresAt: Date.now() + 3600000, // 1 hour
      used: false
    });
    return token;
  }

  async validateAndConsume(token, newPassword) {
    const hashedToken = crypto.createHash('sha256').update(token).digest('hex');
    const record = this.tokens.get(hashedToken);

    if (!record) return { success: false, error: 'Invalid token' };
    if (record.used) return { success: false, error: 'Token already used' };
    if (record.expiresAt < Date.now()) {
      this.tokens.delete(hashedToken);
      return { success: false, error: 'Token expired' };
    }

    // Mark as used BEFORE processing to prevent race conditions
    record.used = true;

    // Validate password strength
    if (!this.isStrongPassword(newPassword)) {
      record.used = false; // Allow retry on validation failure
      return { success: false, error: 'Password too weak' };
    }

    const hash = await bcrypt.hash(newPassword, 12);
    await pool.query('UPDATE users SET password_hash = $1 WHERE id = $2', [hash, record.userId]);
    this.tokens.delete(hashedToken);
    return { success: true, userId: record.userId };
  }

  isStrongPassword(password) {
    return password.length >= 12 && /[A-Z]/.test(password) && /[0-9]/.test(password) && /[^A-Za-z0-9]/.test(password);
  }
}

const resetManager = new PasswordResetManager();

// Session management with sliding window
class SessionStore {
  constructor() {
    this.sessions = new Map();
  }

  create(userId, metadata) {
    const token = generateSessionToken();
    const session = {
      userId,
      token,
      createdAt: Date.now(),
      lastAccess: Date.now(),
      maxAge: 86400000, // 24 hours
      metadata: metadata || {}
    };
    this.sessions.set(token, session);
    return token;
  }

  validate(token) {
    const session = this.sessions.get(token);
    if (!session) return null;

    const now = Date.now();
    // Check absolute expiry
    if (now - session.createdAt > session.maxAge) {
      this.sessions.delete(token);
      return null;
    }
    // Sliding window: extend if accessed within last 30 min
    if (now - session.lastAccess < 1800000) {
      session.lastAccess = now;
    }
    return session;
  }

  revoke(token) {
    this.sessions.delete(token);
  }
}

const sessionStore = new SessionStore();

// Auth middleware
function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing authorization' });
  }
  const token = authHeader.slice(7);
  const session = sessionStore.validate(token);
  if (!session) {
    return res.status(401).json({ error: 'Invalid or expired session' });
  }
  req.user = { id: session.userId, metadata: session.metadata };
  next();
}

// Login endpoint
app.post('/auth/login', async (req, res) => {
  try {
    const { email, password } = req.body;
    if (!email || !password) return res.status(400).json({ error: 'Missing credentials' });

    const result = await pool.query('SELECT id, password_hash, role FROM users WHERE email = $1', [email]);
    if (result.rows.length === 0) {
      // Prevent user enumeration with constant-time fake comparison
      await bcrypt.hash(password, 12);
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const user = result.rows[0];
    const valid = await bcrypt.compare(password, user.password_hash);
    if (!valid) return res.status(401).json({ error: 'Invalid credentials' });

    const token = sessionStore.create(user.id, { role: user.role, email });
    res.json({ token, expiresIn: 86400 });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

