app.post('/auth/reset-request', async (req, res) => {
  try {
    const { email } = req.body;
    if (!email) return res.status(400).json({ error: 'Email required' });

    const result = await pool.query('SELECT id FROM users WHERE email = $1', [email]);
    // Always return success to prevent user enumeration
    if (result.rows.length > 0) {
      const token = await resetManager.createResetToken(result.rows[0].id);
      // In production: send via email. Here we log for testing.
      console.log(`Reset token for ${email}: ${token}`);
    }
    res.json({ message: 'If the email exists, a reset link has been sent' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

// Password reset execution
app.post('/auth/reset', async (req, res) => {
  try {
    const { token, newPassword } = req.body;
    if (!token || !newPassword) return res.status(400).json({ error: 'Missing fields' });

    const result = await resetManager.validateAndConsume(token, newPassword);
    if (!result.success) return res.status(400).json({ error: result.error });

    // Revoke all existing sessions for this user
    for (const [sessionToken, session] of sessionStore.sessions) {
      if (session.userId === result.userId) {
        sessionStore.sessions.delete(sessionToken);
      }
    }
    res.json({ message: 'Password reset successful' });
  } catch (err) {
    res.status(500).json({ error: 'Internal error' });
  }
});

